        sb.append(", opsDetail_1#step2: partition=" + partition + ", offset=" + offset);
        sb.append(", opsDetail_1#step3: partition=" + partition + ", offset=" + offset);
        sb.append(", opsDetail_1#step4: partition=" + partition + ", offset=" + offset);
