        sb.append(", opsDetail_1#step7: partition=" + partition + ", offset=" + offset);
        sb.append(", opsDetail_1#step8: partition=" + partition + ", offset=" + offset);
        sb.append(", opsDetail_1#step9: partition=" + partition + ", offset=" + offset);
        sb.append(", opsDetail_1#step10: partition=" + partition + ", offset=" + offset);
        sb.append(", opsDetail_1#step11: partition=" + partition + ", offset=" + offset);
        sb.append(", opsDetail_1#step12: partition=" + partition + ", offset=" + offset);
